INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (177, 357, 'B Grade BOPET Film with thickness 6.0-9.0Microns', '../upload/image/20211216/20211216092910_66247.jpg', '<p><span style="font-family:Tahoma;font-size:18px;color:#009900;">B Grade BOPET Film with thickness 6.0-9.0Microns</span><br/></p><p><span style="font-family:Tahoma;font-size:18px;color:#009900;">6.5,7.5, 8.5, 9.5, 11.5 Microns*620MM. BOPET film (polyester film) clear transparent , uncoating and unprinting. </span></p> <span style="font-family:Tahoma;font-size:18px;color:#009900;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">Grade A (Standard packing- pallets+wooden board, 6inch core ) </span><br/> </span><br/>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (177, 358, '出口巴基斯坦和智利的货，需要做产地证的，需在报关之前办理产地证，', '../', '<p><!--StartFragment --></p><div> 即日起，所有出口巴基斯坦和智利的货，需要做产地证的，需在报关之前办理产地证，<br/> 因为报关需要填报原产地证号的，如报关没有填报产地证号，货物到达目的港，不再享受关税优惠！<br/> 1.光有F号码不行，要有联网数据才能报得了关，不然就是报关报不了享惠，对目的港那边有无影响请客户自行确认<br/> 2.产地证上有个港口对应提单上的港口，也对应报关时候的港口，都要对应起来的<br/> 3.产地证数据出来后入海关库里可能有时间问题,要提前几个工作日申请的。<br/> 具体的原产地查询网址：<img src="data:image/png;base64,"/>http://cas.chinaport.gov.cn/cas/login?service=http%3A%2F%2Fweb.chinaport.gov.cn%2FCooq%2Findex.html<br/> </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (177, 359, '4.5Mic BOPET film clear transparent , unprinting & with one side coated the other side uncoating (for priting and laminating)', '../upload/image/20211216/20211216093057_74000.jpg', '<p></p> <p><span style="color:#009900;font-family:Tahoma;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">4.5Mic BOPET TTR film With </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">One Side Coated </span><br/> </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">4.5Mic BOPET film Clear transparent, Unprinting. With one side coated for TTR usage (Thernal transfer ribbons) , the other side uncoating,</span></p> <p><span style="font-family:Tahoma;font-size:18px;color:#009900;">Besides </span><span style="color:#009900;font-family:Tahoma;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">4.5Mic BOPET film clear transparent , with two sides</span><span style="color:#009900;font-family:Tahoma;font-size:18px;"> unprinting &amp; </span><span style="font-family:Tahoma;font-size:18px;color:#009900;"> uncoating (for printing and laminating),&nbsp; </span></span><span style="font-family:Tahoma;font-size:18px;color:#009900;">and there are one side coated 4.5Mic BOPET TTR film.</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">this is : </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">4.5Mic BOPET film Clear transparent, Unprinting and one side coated for TTR usage (Thernal transfer ribbons) , the other side uncoating,</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> and you can use print and laminating at the uncoating side), the coated side was very smooth , and it was suit for the label machine to print the labels and the printing speed can</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> be fast, if without the smooth side. The label machine will be can not make sure the fast speed during printing.) </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Thickness: 4.5Microns (4.4Microns film +0.1microns coating layer)</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Width: 1010MM mainly, 680MM mainly, 650MM</span><span style="color:#009900;font-family:Tahoma;font-size:18px;">,900MM,1400MM...</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Length:12000-32000M (18500M mainly)</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Inner paper tube core: 6 inches /</span><span style="color:#009900;font-family:Tahoma;font-size:18px;">152MM</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Packing: Standard packing ( bubble film +kraft paper +plastic insert) </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Quantity : 150tons /month</span></p> <p><br/></p>', '2026-09-06 20:58:45');